/* harmony default export */ __webpack_exports__["default"] = ({
  mixins: [_common_fa_mixin_js__WEBPACK_IMPORTED_MODULE_0__["loginfunc"]],
  onLoad() {
    this.isThreeLogin = true;

    // 如果仅有账号登录一种方式则直接跳转至登录页
    if (this.checkLogintype('account') && this.vuex_config.logintypearr.length === 1) {
      this.$u.route({
        url: '/pages/login/login',
        type: 'redirectTo'
      });
    }
  },
  // 必须要在onReady生命周期，因为onLoad生命周期组件可能尚未创建完毕
  onReady() {
    if (this.checkLogintype('mobile')) {
      this.$refs.uForm.setRules(this.rules);
    }
  },
  data() {
    return {
      labelPosition: 'top',
      border: false,
      errorType: ['message'],
      form: {
        mobile: '',
        captcha: ''
      },
      rules: {
        mobile: [{
          required: true,
          message: '请输入手机号码',
          // 可以单个或者同时写两个触发验证方式
          trigger: ['change', 'blur']
        }, {
          // 自定义验证函数，见上说明
          validator: (rule, value, callback) => {
            return this.$u.test.mobile(value);
          },
          message: '手机号码不正确',
          trigger: ['change', 'blur']
        }],
        captcha: [{
          required: true,
          message: '请输入验证码',
          trigger: 'change'
        }]
      },
      isThreeLogin: false,
      codeTips: ''
    };
  },
  methods: {
    codeChange(text) {
      this.codeTips = text;
    },
    // 获取验证码
    getCode: async function () {
      if (!this.$u.test.mobile(this.form.mobile)) {
        this.$u.toast('手机号码格式不正确！');
        return;
      }
      if (this.$refs.uCode.canGetCode) {
        let res = await this.$api.getSmsSend({
          mobile: this.form.mobile,
          event: 'mobilelogin'
        });
        setTimeout(() => {
          this.$u.toast(res.msg);
        }, 50);
        if (res.code == 1) {
          this.$refs.uCode.start();
        }
      } else {
        this.$u.toast('倒计时结束后再发送');
      }
    },
    goThreeLogin: async function () {
      this.goMpLogin();
    },
    goLogin: function () {
      this.$refs.uForm.validate(async valid => {
        if (valid) {
          if (this.vuex_wx_uid) {
            this.form.wx_user_id = this.vuex_wx_uid;
          }
          let res = await this.$api.mobilelogin(this.form);
          if (!res.code) {
            this.$u.toast(res.msg);
            return;
          }
          this.$u.vuex('vuex_token', res.data.token);
          this.success();
        } else {
          this.$u.toast('验证失败');
        }
      });
    }
  }
});

